    s_CHILDHOOD_ILLNESSES(py_tuple(vec![py_tuple(vec![py_tuple(vec![py_str("measles")]), py_str("Measles is a viral illness: a high fever, cough and sore red eyes, then a blotchy rash that starts behind the ears and spreads down the body. It is caught by coughing and is infectious from about four days before the rash until four days after it appears, and it can cause pneumonia, so ring the GP the same day rather than waiting it out. Keep a child off school for those four days, and tell the GP if a pregnant woman or anyone with a weak immune system has been in contact.")]), py_tuple(vec![py_tuple(vec![py_str("mumps")]), py_str("Mumps swells the salivary gland in front of the ear, so the jaw and cheek look puffy on one side or both, with fever and a headache. It spreads by coughs and saliva and is infectious from about two days before the swelling until five days after it starts; in teenagers and adults it can also inflame the testicles or the ovaries. Keep a child off school for five days from the swelling, and use cold drinks and soft food if chewing hurts.")]), py_tuple(vec![py_tuple(vec![py_str("rubella"), py_str("german measles")]), py_str("Rubella is a mild viral illness - a fine pink rash, tender glands behind the ears and a low fever - and in a child it is often so slight it goes unnoticed. It is infectious from about a week before the rash to six days after it, and it matters mainly because it is dangerous to an unborn baby, so anyone pregnant who has been near it should ring their midwife or GP straight away. A child stays off school for six days after the rash appears.")]), py_tuple(vec![py_tuple(vec![py_str("slapped cheek"), py_str("fifth disease"), py_str("parvovirus")]), py_str("Slapped cheek is a virus that gives bright red cheeks, as if the child has been slapped, sometimes with a lacy pink rash on the body and a mild fever. It is most infectious in the days before the rash shows, so by the time the cheeks are red the worst is usually over, and once the child feels well they can go back to school. Tell anyone pregnant who has been in contact, because it can affect an unborn baby.")]), py_tuple(vec![py_tuple(vec![py_str("scarlet fever"), py_str("scarletina")]), py_str("Scarlet fever is a bacterial infection from the same germ as strep throat: a sore throat and fever, then a rough red rash like sandpaper and a strawberry-red tongue, and it needs antibiotics. It stops being infectious 24 hours after the first dose, so ring the GP the same day - untreated it can lead to rheumatic fever. A child can go back to school a day after starting the medicine if they feel well in themselves.")]), py_tuple(vec![py_tuple(vec![py_str("whooping cough"), py_str("pertussis")]), py_str("Whooping cough starts like a cold, then turns into fits of coughing that end in a whoop or in vomiting, and the cough can run for two to three months. It spreads by coughing and is infectious from the first symptoms until about three weeks after the coughing fits begin, or 48 hours after antibiotics; it is most dangerous to babies under six months, so ring the GP as soon as you suspect it. A newborn who has been near a case needs telling their doctor the same day.")]), py_tuple(vec![py_tuple(vec![py_str("hand foot and mouth"), py_str("hand foot mouth"), py_str("hand foot and mouth disease"), py_str("hfmd")]), py_str("Hand, foot and mouth is a common virus in small children: mouth ulcers, then small spots or blisters on the palms, the soles and the nappy area, with a mild fever. It spreads by coughs, saliva and nappy changes and is most infectious in the first week, but once the child is well enough to eat and drink they can go back to nursery - there is no need to wait for the spots to go. See the GP if they will not drink at all, or are drowsy.")]), py_tuple(vec![py_tuple(vec![py_str("glandular fever"), py_str("kissing disease")]), py_str("Glandular fever is a viral infection with a bad sore throat, swollen glands in the neck, a fever and an exhaustion that can drag on for weeks. It spreads by saliva - bottles, cups, cutlery - and the tiredness usually eases over a month or two, though it can come back for a while. No sport or heavy lifting for about four weeks, because the spleen can swell; see the GP if swallowing is very painful, they are badly unwell, or the tiredness is not lifting.")]), py_tuple(vec![py_tuple(vec![py_str("impetigo")]), py_str("Impetigo is a bacterial skin infection: golden, crusty sores or blisters, usually round the nose and mouth or on the hands, and it is very infectious until the sores have crusted or 48 hours of antibiotics have been taken. Keep it covered, wash your hands after touching it, and do not share towels; a pharmacist or GP can give a cream or tablets. A child stays off school until the sores are crusted or treated for two days.")]), py_tuple(vec![py_tuple(vec![py_str("laryngitis")]), py_str("Laryngitis is inflammation of the voice box, usually after a cold or a lot of shouting: a hoarse or lost voice, a dry tickle and sometimes a sore throat, and it settles within one to two weeks. Rest the voice - do not whisper, which strains it more than talking does - drink plenty and treat it like the cold it is. See the GP if it lasts over three weeks, or if breathing or swallowing becomes hard.")])]));
